 * own slowness. For chunked responses, stop as soon as the
 * terminating chunk ("0\r\n\r\n") is seen: relying on server
 * close breaks on keep-alive servers (would block until socket
 * timeout). */
{
    long t_fb = ctx->first_byte_ms;
