    const char* date = strcasestr(raw, "\r\nDate:");
    const char* ratel = strcasestr(raw, "x-ratelimit");
    const char* conn = strcasestr(raw, "Connection:");
    char server_val[48] = "?";
    char date_val[40] = "-";
    char conn_val[16] = "-";
