        date += strspn(date, "\r\nDate: \t");
        while (k < 39 && date[k] && date[k] != '\r' && date[k] != '\n')
            { date_val[k] = date[k]; k++; }
        date_val[k] = '\0';
    }
    if (conn && conn < body_start) {
        int k = 0;
        conn += strspn(conn, "Connection: \t");
        while (k < 15 && conn[k] && conn[k] != '\r' && conn[k] != '\n')
            { conn_val[k] = conn[k]; k++; }
        conn_val[k] = '\0';
    }
    if (ratel && ratel < body_start) {
        int k = 0;
        const char* p = ratel;
        while (k < 159 && p[k] && p[k] != '\r') { ratel_line[k] = p[k]; k++; }
        ratel_line[k] = '\0';
    }

    if (!eof) {
        struct timespec ts_body_start, ts_body_end;
        clock_gettime(CLOCK_MONOTONIC, &ts_body_start);
        while (resp_pos < resp_cap - 1) {
            if (content_length >= 0 && (long)resp_pos >= content_length)
                break;
            /* Chunked: stop once the final-chunk marker is in the
